let _markdown = "\n\nWhat is this? [#what-is-this]\n\n<FeedbackBlock id=\"caaa7b96ffdfed07\" body=\"Fumadocs Core offers server-side functions and headless components to build docs on any React.js frameworks like Next.js.\">\n  Fumadocs Core offers server-side functions and headless components to build docs on any React.js frameworks like Next.js.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"8f63ff2423da0f2a\" body=\"Search (built-in: Orama, Algolia Search)Breadcrumb, Sidebar, TOC ComponentsRemark/Rehype PluginsAdditional utilities\">\n  * Search (built-in: Orama, Algolia Search)\n  * Breadcrumb, Sidebar, TOC Components\n  * Remark/Rehype Plugins\n  * Additional utilities\n</FeedbackBlock>\n\n<Callout title=\"Tip\">\n  It can be used without Fumadocs UI, in other words, it's headless.\n\n  For beginners and normal usages, use [Fumadocs UI](/docs/ui).\n</Callout>\n\nInstallation [#installation]\n\n<FeedbackBlock id=\"4a9409c3b6f6a381\" body=\"No other dependencies required.\">\n  No other dependencies required.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install fumadocs-core\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add fumadocs-core\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add fumadocs-core\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add fumadocs-core\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"6f275eb42a9c817b\" body=\"For some components, a framework provider is needed:\">\n  For some components, a framework provider is needed:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Next.js\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Next.js\">\n      Next.js\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"React Router\">\n      React Router\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Tanstack Start/Router\">\n      Tanstack Start/Router\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Waku\">\n      Waku\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Next.js\">\n    ```tsx\n    import type { ReactNode } from 'react';\n    import { NextProvider } from 'fumadocs-core/framework/next';\n\n    export function RootLayout({ children }: { children: ReactNode }) {\n      // or if you're using Fumadocs UI, use `<RootProvider />`\n      return <NextProvider>{children}</NextProvider>;\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"React Router\">\n    ```tsx\n    import type { ReactNode } from 'react';\n    import { ReactRouterProvider } from 'fumadocs-core/framework/react-router';\n\n    export function Root({ children }: { children: ReactNode }) {\n      return <ReactRouterProvider>{children}</ReactRouterProvider>;\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Tanstack Start/Router\">\n    ```tsx\n    import type { ReactNode } from 'react';\n    import { TanstackProvider } from 'fumadocs-core/framework/tanstack';\n\n    export function Root({ children }: { children: ReactNode }) {\n      return <TanstackProvider>{children}</TanstackProvider>;\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Waku\">\n    ```tsx\n    import type { ReactNode } from 'react';\n    import { WakuProvider } from 'fumadocs-core/framework/waku';\n\n    export function Root({ children }: { children: ReactNode }) {\n      return <WakuProvider>{children}</WakuProvider>;\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock\n  id=\"70796f7b228f70c8\"\n  body=\"It offers simple document searching as well as components for building a\ngood docs.\"\n>\n  It offers simple document searching as well as components for building a\n  good docs.\n</FeedbackBlock>\n\n<Cards>\n  <Card title=\"Breadcrumb\" href=\"/docs/headless/components/breadcrumb\" description=\"The navigation component at the top of screen\" />\n\n  <Card title=\"TOC\" href=\"/docs/headless/components/toc\" description=\"A Table of Contents with active anchor observer\" />\n\n  <Card title=\"Source API\" href=\"/docs/headless/source-api\" description=\"The unified interface for handling content sources\" />\n\n  <Card title=\"Search\" href=\"/docs/headless/search\" description=\"Implement document searching\" />\n</Cards>\n";
